page {
  background-color: #f4f6fa;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Helvetica, "PingFang SC", "Microsoft YaHei", sans-serif;
  color: #1f2933;
  font-size: 28rpx;
  box-sizing: border-box;
}

view,
text,
input,
button {
  box-sizing: border-box;
}

Page({
  data: {
    principal: '',
    rate: '',
    months: '',
    monthly: '0.00',
    totalInterest: '0.00',
    totalPayment: '0.00',
    error: ''
  },

  onPrincipalInput(e) {
    this.setData({ principal: e.detail.value, error: '' });
  },

  onRateInput(e) {
    this.setData({ rate: e.detail.value, error: '' });
  },

  onMonthsInput(e) {
    this.setData({ months: e.detail.value, error: '' });
  },

  onCalc() {
    const principalRaw = (this.data.principal || '').trim();
    const rateRaw = (this.data.rate || '').trim();
    const monthsRaw = (this.data.months || '').trim();

    if (principalRaw === '' || rateRaw === '' || monthsRaw === '') {
      this.setData({ error: '请填写贷款金额、年利率和期限' });
      return;
    }

    const principal = Number(principalRaw);
    const rate = Number(rateRaw);
    const months = Number(monthsRaw);

    if (!isFinite(principal) || !isFinite(rate) || !isFinite(months)) {
      this.setData({ error: '请输入有效数字' });
      return;
    }
    if (principal <= 0) {
      this.setData({ error: '贷款金额必须大于 0' });
      return;
    }
    if (rate < 0) {
      this.setData({ error: '年利率不能为负数' });
      return;
    }
    if (months <= 0 || Math.floor(months) !== months) {
      this.setData({ error: '期限必须为正整数（月）' });
      return;
    }

    let monthly;
    if (rate === 0) {
      monthly = principal / months;
    } else {
      const r = rate / 100 / 12;
      const pow = Math.pow(1 + r, months);
      monthly = (principal * r * pow) / (pow - 1);
    }

    const totalPayment = monthly * months;
    const totalInterest = totalPayment - principal;

    this.setData({
      monthly: this.format(monthly),
      totalInterest: this.format(totalInterest),
      totalPayment: this.format(totalPayment),
      error: ''
    });
  },

  onReset() {
    this.setData({
      principal: '',
      rate: '',
      months: '',
      monthly: '0.00',
      totalInterest: '0.00',
      totalPayment: '0.00',
      error: ''
    });
  },

  format(num) {
    if (!isFinite(num)) {
      return '0.00';
    }
    const rounded = Math.round(num * 100) / 100;
    return rounded.toFixed(2);
  },

  onShareAppMessage() {
    return {
      title: '等额本息房贷计算器',
      path: 'pages/index/index'
    };
  }
});

page {
  background-color: #f4f6fa;
  min-height: 100vh;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Helvetica Neue", Arial, sans-serif;
  color: #2c3e50;
}

.container {
  padding: 24rpx 28rpx 48rpx;
  box-sizing: border-box;
}

.card {
  background-color: #ffffff;
  border-radius: 20rpx;
  padding: 32rpx 30rpx;
  margin-bottom: 24rpx;
  box-shadow: 0 4rpx 20rpx rgba(31, 111, 235, 0.08);
}

.card-title {
  font-size: 30rpx;
  font-weight: 600;
  color: #1f6feb;
  margin-bottom: 24rpx;
  padding-left: 16rpx;
  border-left: 8rpx solid #1f6feb;
  line-height: 1.2;
}

.field {
  margin-bottom: 28rpx;
}

.field:last-child {
  margin-bottom: 0;
}

.field-label {
  display: block;
  font-size: 26rpx;
  color: #5b6b7c;
  margin-bottom: 12rpx;
}

.field-input {
  width: 100%;
  height: 88rpx;
  background-color: #f4f6fa;
  border: 2rpx solid #e1e6ed;
  border-radius: 12rpx;
  padding: 0 20rpx;
  font-size: 32rpx;
  color: #2c3e50;
  box-sizing: border-box;
}

.field-input:focus {
  border-color: #1f6feb;
}

.field-hint {
  font-size: 22rpx;
  color: #97a3b0;
  margin-top: 10rpx;
}

.button-row {
  display: flex;
  gap: 20rpx;
  margin-bottom: 24rpx;
}

.btn {
  flex: 1;
  height: 92rpx;
  line-height: 92rpx;
  text-align: center;
  font-size: 32rpx;
  font-weight: 600;
  border-radius: 12rpx;
  box-sizing: border-box;
}

.btn-primary {
  background-color: #1f6feb;
  color: #ffffff;
}

.btn-primary:active {
  background-color: #1857c4;
}

.btn-default {
  background-color: #ffffff;
  color: #1f6feb;
  border: 2rpx solid #1f6feb;
}

.btn-default:active {
  background-color: #eef4ff;
}

.error-tip {
  background-color: #fff1f0;
  border: 2rpx solid #ffccc7;
  color: #d4380d;
  border-radius: 12rpx;
  padding: 20rpx 24rpx;
  font-size: 26rpx;
  margin-bottom: 24rpx;
  line-height: 1.5;
}

.result-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24rpx 0;
  border-bottom: 2rpx solid #f0f3f7;
}

.result-row:last-child {
  border-bottom: none;
}

.result-label {
  font-size: 28rpx;
  color: #5b6b7c;
}

.result-value {
  font-size: 34rpx;
  font-weight: 600;
  color: #2c3e50;
}

.result-value-highlight {
  font-size: 40rpx;
  font-weight: 700;
  color: #1f6feb;
}

.unit {
  font-size: 24rpx;
  color: #97a3b0;
  margin-left: 6rpx;
  font-weight: 400;
}
